function localeCatalogText(language, text) {
  if (!text) return "";
  const value = String(text);
  return catalogLabelTranslations[language]?.[value]
    ?? productNameTranslations[language]?.[value]
    ?? translations[language]?.[value]
    ?? value;
}

for (const [language, entries] of Object.entries(extraTranslations)) {
  if (!translations[language]) translations[language] = {};
  Object.assign(translations[language], entries);
}

