for (const [language, entries] of Object.entries(requestedLanguageTranslations)) {
  if (!translations[language]) translations[language] = {};
  Object.assign(translations[language], entries);
}

const LanguageContext = createContext(null);

export function LanguageProvider({ children }) {
  const [language, setLanguage] = useState(() => {
    try {
      const savedLanguage = window.localStorage.getItem("mtaa-market-language");
      return languageOptions.some((option) => option.code === savedLanguage && !option.disabled) ? savedLanguage : "en";
    } catch {
      return "en";
    }
  });

  useEffect(() => {
    document.documentElement.lang = language;
    document.title = localeCatalogText(language, "Mtaa Market | Shop local");
    const description = document.querySelector('meta[name="description"]');
    if (description) {
      description.setAttribute("content", localeCatalogText(language, "Shop unique products from your neighborhood with Mtaa Market."));
    }
    try {
      window.localStorage.setItem("mtaa-market-language", language);
    } catch {
    }
  }, [language]);

  function t(text) {
    if (!text) return "";
    return localeCatalogText(language, text);
  }

  return (
    <LanguageContext.Provider value={{ language, setLanguage, languageOptions, t }}>
      {children}
    </LanguageContext.Provider>
  );
}

export function useLanguage() {
  const context = useContext(LanguageContext);
  if (!context) throw new Error("useLanguage must be used within LanguageProvider");
  return context;
}